import{_ as t,o as s,c as r,a2 as o}from"./chunks/framework.CQdiwDJy.js";const g=JSON.parse('{"title":"Authoring skills","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/skill-authoring.md","filePath":"en/reference/skill-authoring.md","lastUpdated":1788601681000}'),i={name:"en/reference/skill-authoring.md"};function l(a,e,n,d,c,h){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="authoring-skills" tabindex="-1">Authoring skills <a class="header-anchor" href="#authoring-skills" aria-label="Permalink to &quot;Authoring skills&quot;">​</a></h1><p>This page targets contributors writing skills for the <strong>Tau repository itself</strong>. For user-facing skills, see the <a href="/Tau/en/guide/skills.html">skills guide</a>.</p><h2 id="the-three-layer-skill-md-model" tabindex="-1">The three-layer SKILL.md model <a class="header-anchor" href="#the-three-layer-skill-md-model" aria-label="Permalink to &quot;The three-layer SKILL.md model&quot;">​</a></h2><p>SKILL.md files in this repo come in three layers; placing one in the wrong layer is a governance error:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>Nature</th></tr></thead><tbody><tr><td>L1</td><td><code>.claude/skills/*/SKILL.md</code></td><td>root dev-workflow skills (build/test/release/docs), cross-cutting</td></tr><tr><td>L2</td><td><code>packages/&lt;pkg&gt;/SKILL.md</code>, <code>app/&lt;app&gt;/SKILL.md</code></td><td>package-owned skills, versioned with what they govern</td></tr><tr><td>L3</td><td><code>packages/skills/bundled/&lt;name&gt;/</code></td><td>shipped <strong>product content</strong> (runtime data) users see via <code>tau skill list</code></td></tr></tbody></table><p>The root <code>SKILL.md</code> is a <strong>router</strong>: it routes by subsystem to the one designated skill file and normative spec. Update the routing table when adding a skill — every dev tool has exactly one designated entry.</p><h2 id="writing-rules" tabindex="-1">Writing rules <a class="header-anchor" href="#writing-rules" aria-label="Permalink to &quot;Writing rules&quot;">​</a></h2><ul><li><strong>Frontmatter required</strong>: <code>name</code>, <code>description</code> (one sentence — when does this trigger), <code>risk</code>.</li><li><strong>Content shape</strong>: one-line positioning first (what this is, what it is not), then the operating paths, then common pitfalls. Prefer short and precise over long and complete.</li><li><strong>Declarative commands</strong>: L3 skill commands are declarations (they expand to intents), not scripts; declared risk passes the same gate as built-ins.</li><li><strong>Spec references</strong>: skills index and route; normative detail lives in <code>AGENTS/&lt;topic&gt;.md</code> linked from the skill — every rule is defined in exactly one place.</li></ul><h2 id="user-skills-vs-repo-skills" tabindex="-1">User skills vs repo skills <a class="header-anchor" href="#user-skills-vs-repo-skills" aria-label="Permalink to &quot;User skills vs repo skills&quot;">​</a></h2><ul><li>Capabilities for <strong>users</strong> → L3 <code>packages/skills/bundled/</code>, or <code>$TAU_HOME/skills/</code> / workspace <code>./skills/</code> (not in the repo).</li><li>Workflows for the <strong>development AI agent</strong> → L1 or L2, in the repo, reviewed with the code.</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><p>A skill PR must include: complete frontmatter, the root routing table (for new root skills), a governance table row (<code>AGENTS/architecture.md</code>, for new locations), and a <code>tau skill list</code> output verification.</p>',12)])])}const p=t(i,[["render",l]]);export{g as __pageData,p as default};
